const eventNames=()=>({wedding:t('Pulm','Wedding'),birthday:t('Sünnipäev','Birthday'),summer:t('Suvepäevad','Summer event'),other:t('Muu sündmus','Other event')});
const packageNames=()=>({half:t('Pulmakorraldus · pool päeva','Wedding planning · half day'),full:t('Pulmakorraldus · terve päev','Wedding planning · full day'),coordination:t('Pulmapäeva koordineerimine','Wedding-day coordination')});
const locationNames=()=>({local:'Saaremaa / Muhumaa / Tartumaa',mainland:t('Muu Mandri-Eesti','Elsewhere in mainland Estonia'),hiiu:'Hiiumaa',islands:t('Muud saared','Other islands')});
let eventState={event:'wedding',guests:60,location:'local',package:'half',decor:'none',styling:false,dinner:false,visit:false,website:false,extraHours:0,lateHours:0,occasion:''};
try{const saved=JSON.parse(sessionStorage.getItem('eheEventInputsV3'));if(saved){EheLogic.estimate(saved);eventState={...eventState,...saved}}}catch{}
function calculatorMarkup(){return `<section class="calculator" id="calculator"><span class="eyebrow">${t('TEIE SÜNDMUSE ESIMENE PLAAN','A FIRST PLAN FOR YOUR EVENT')}</span><h2>${t('Arvutame koos.','Let’s work it out.')}</h2><p>${t('Valige sündmuse liik, külaliste arv ja sobivad teenused. Näete kohe esialgset kogusummat.','Choose your event, guest count and services to see an instant estimate.')}</p><div class="event-tabs" role="group" aria-label="${t('Sündmuse liik','Event type')}">${Object.entries(eventNames()).map(([id,name])=>`<button type="button" data-event="${id}" aria-pressed="${eventState.event===id}">${name}</button>`).join('')}</div><div class="calc-grid"><form id="calc"><div id="event-fields" class="fields"></div></form><aside class="quote" id="quote" aria-live="polite"></aside></div><p class="small">${t('Hinnang sisaldab valitud teenuseid ja dekoratsioonipaketi sisu. Peokoht, toitlustus, fotograaf ning eraldi tellitud renditooted ei sisaldu. Lõplik pakkumine kinnitatakse pärast detailide täpsustamist.','The estimate includes your selected services and decoration package contents. Venue, catering, photography and separately ordered rentals are excluded. The final quote is confirmed after discussing the details.')}</p></section>`}
function drawEventFields(){
 const v=eventState,wedding=v.event==='wedding',party=['birthday','summer'].includes(v.event);
 $('#event-fields').innerHTML=`<label>${t('Külaliste arv','Number of guests')}<input id="guests" type="number" min="1" max="1000" step="1" required></label><label>${t('Asukoht','Location')}<select id="location">${Object.entries(locationNames()).map(([id,name])=>`<option value="${id}">${name}</option>`).join('')}</select></label>${wedding?`<label class="wide">${t('Pulmateenus','Wedding service')}<select id="wedding-package">${Object.entries(packageNames()).map(([id,name])=>`<option value="${id}">${name}</option>`).join('')}</select></label><p id="package-note" class="wide small"></p><label class="wide">${t('Dekoratsioonipakett','Decoration package')}<select id="decor"><option value="none">${t('Ilma dekoratsioonipaketita','No decoration package')}</option><option value="mini">Mini</option><option value="midi">Midi</option><option value="maxi">Maxi</option></select></label><p id="decor-note" class="wide small"></p><label>${t('Lisatunnid enne südaööd','Extra hours before midnight')}<input id="extra-hours" type="number" min="0" max="24" step="0.5" required></label><label>${t('Koordineerimine pärast 00:00','Coordination after midnight')}<input id="late-hours" type="number" min="0" max="24" step="0.5" required></label><p class="wide small">${t('Sisestage tunnid eraldi, sama tundi mõlemasse lahtrisse märkimata.','Enter the hours separately, without counting the same hour in both fields.')}</p><label class="check"><input id="visit" type="checkbox">${t('Ühine pulmakoha külastus','Joint wedding venue visit')}</label><label class="check"><input id="website" type="checkbox">${t('Pulmalehe koostamine ja haldamine','Wedding website creation and management')}</label><label class="check"><input id="dinner" type="checkbox">${t('Pulmaeelse õhtusöögi korraldamine ja koordineerimine','Pre-wedding dinner planning and coordination')}</label>`:`${party?`<p class="wide package-note">${t('Hinnas on korraldamine ja koordineerimine kuni 8-tunniseks sündmuseks.','Planning and coordination for an event of up to 8 hours are included.')}</p>`:''}<label class="wide">${v.event==='birthday'?t('Peo soovid või teema','Party wishes or theme'):v.event==='summer'?t('Tegevused ja programmi soovid','Activities and programme wishes'):t('Millist sündmust planeerite?','What event are you planning?')}<input id="occasion" maxlength="200" type="text"></label><label class="check"><input id="styling" type="checkbox">${t('Dekoreerimine','Decorating')}</label>`}`;
 $('#guests').value=v.guests;$('#location').value=v.location;
 if(wedding){$('#wedding-package').value=v.package;$('#decor').value=v.decor;$('#extra-hours').value=v.extraHours;$('#late-hours').value=v.lateHours;for(const k of ['visit','website','dinner'])$('#'+k).checked=v[k]}else{$('#styling').checked=v.styling;$('#occasion').value=v.occasion}
 $('#calc').oninput=updateQuote;$('#calc').onsubmit=e=>e.preventDefault();updateQuote();
}
function initCalculator(){document.querySelectorAll('[data-event]').forEach(b=>b.onclick=()=>{eventState.event=b.dataset.event;document.querySelectorAll('[data-event]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));drawEventFields()});drawEventFields()}
function quoteLabels(v){return {service:v.event==='wedding'?packageNames()[v.package]:t('Korraldamine ja koordineerimine','Planning and coordination'),transport:t('Transport','Travel'),decorating:v.event==='wedding'?t('Dekoratsioonipakett ','Decoration package ')+(v.decor==='none'?'':v.decor[0].toUpperCase()+v.decor.slice(1)):t('Dekoreerimine','Decorating'),extraHours:t('Lisatunnid','Extra hours'),lateHours:t('Koordineerimine pärast 00:00','Coordination after midnight'),assistant:t('Lisakoordinaator','Additional coordinator'),visit:t('Ühine kohakülastus koos transpordiga','Joint venue visit with travel'),website:t('Pulmalehe koostamine ja haldamine','Wedding website'),dinner:t('Pulmaeelne õhtusöök','Pre-wedding dinner')}}
function updateQuote(){
 if(!siteSettings){$('#quote').textContent=t('Kehtivaid hindu ei saanud laadida. Palun värskenda lehte või küsi pakkumist aadressilt karen@eheevents.ee.','Current prices could not be loaded. Please refresh or request a quote at karen@eheevents.ee.');return}
 if(!$('#calc').checkValidity()){$('#quote').textContent=t('Kontrollige külaliste arvu ja tundide välju. Külaliste arv peab olema täisarv 1–1000.','Check the guest count and hours. Guest count must be a whole number from 1 to 1,000.');return}
 const wedding=eventState.event==='wedding';Object.assign(eventState,{guests:+$('#guests').value,location:$('#location').value});
 if(wedding){eventState.package=$('#wedding-package').value;eventState.decor=$('#decor').value;eventState.extraHours=+$('#extra-hours').value;eventState.lateHours=+$('#late-hours').value;for(const k of ['visit','website','dinner'])eventState[k]=$('#'+k).checked;
 $('#package-note').textContent=eventState.package==='coordination'?t('Sisaldab tutvustavat kõnet, eelneva päeva ülevaatust, ajakava ettevalmistamist ja kuni 14 tundi koordineerimist.','Includes an introductory call, a prior-day review, timeline preparation and up to 14 hours of coordination.'):t('Sisaldab ettevalmistusi, kliendisuhtlust ja koordineerimist pulmapäeval kuni ','Includes preparations, client communication and wedding-day coordination for up to ')+(eventState.package==='half'?7:12)+t(' tundi.',' hours.');
 const decorNotes={none:'',mini:t('Laudade, tervitusala ja tseremooniakaare lihtne kujundus. Küünlad, küünlajalad, vaasid, kaar, tervitussilt ja lihtsad laualilleseaded koos paigalduse ning mahavõtuga.','Simple table, welcome-area and ceremony-arch styling. Candles, holders, vases, arch, welcome sign and simple table flowers, including setup and removal.'),midi:t('Peo-, tervitus- ja tseremooniaala kujundus. Küünlad, küünlajalad, vaasid, kaar, tervitussilt, lilleseaded, tekstiilid, istumisplaan ja kohasildid.','Reception, welcome and ceremony styling. Candles, holders, vases, arch, welcome sign, flowers, textiles, seating plan and place cards.'),maxi:t('Terviklik visuaalne kontseptsioon koos dekoratsioonidega tseremoonia-, tervitus- ja peoalal. Lisaks fotonurk.','A complete visual concept with decorations for the ceremony, welcome and reception areas, plus a photo corner.')};$('#decor-note').textContent=decorNotes[eventState.decor];$('#decor-note').hidden=eventState.decor==='none';
 }else{eventState.styling=$('#styling').checked;eventState.occasion=$('#occasion').value}
 const q=EheLogic.estimate(eventState);try{sessionStorage.setItem('eheEventInputsV3',JSON.stringify(eventState))}catch{}
 const labels=quoteLabels(eventState);
 $('#quote').innerHTML=`<span class="eyebrow">${eventNames()[eventState.event]}</span><h3>${t('Teie hinnang','Your estimate')}</h3>${Object.entries(q.rows).filter(([k,v])=>v!==0).map(([k,v])=>`<div class="quote-row"><span>${labels[k]}</span><span>${v===null?t('Pakkumise alusel','By quotation'):money(v)}</span></div>`).join('')}<p class="small">${q.complete?t('Kokku','Total'):t('Teadaolevate teenuste summa','Known services subtotal')}</p><div class="total">${money(q.total)}</div>${wedding&&q.rows.assistant>0?`<p class="small">${t('Hinnang sisaldab lisakoordinaatorit vastavalt külaliste arvule.','The estimate includes an additional coordinator based on the guest count.')}</p>`:''}<p class="small">${q.complete?t('Esialgne hinnang','Initial estimate'):t('Korraldusteenuse hind lisandub personaalse pakkumise alusel. See ei ole kogu sündmuse hind.','Event service pricing is added through a personal quote. This is not the full event price.')}</p><a id="quote-contact" class="button" href="${url('/contact/')}">${t('Küsi personaalset pakkumist','Request your personal quote')} ↗</a>`;
 $('#quote-contact').onclick=()=>{try{sessionStorage.setItem('eheQuote',JSON.stringify({version:3,...eventState,...q}))}catch{}};
}
function eventInquiry(q){const labels=quoteLabels(q);return [eventNames()[q.event],q.guests+t(' külalist',' guests'),t('Asukoht: ','Location: ')+locationNames()[q.location],q.occasion||'',...Object.entries(q.rows).filter(([k,v])=>v!==0).map(([k,v])=>labels[k]+': '+(v===null?t('Pakkumise alusel','By quotation'):money(v))),(q.complete?t('Kokku: ','Total: '):t('Teadaolevate teenuste summa: ','Known services subtotal: '))+money(q.total),!q.complete?t('Korraldusteenuse hind vajab pakkumist.','Event service pricing requires a quote.'):''].filter(Boolean).join('\n')}
